import { Router } from "express";
import { InventoryLoanController } from "./inventory-loan.controller";
import { authMiddleware } from "../../middleware/auth.middleware";
import { rbacMiddleware } from "../../middleware/rbac.middleware";
const router = Router();
const controller = InventoryLoanController;
router.get("/", authMiddleware, controller.getAll);
router.get("/:id", authMiddleware, controller.getById);
router.post("/", authMiddleware, rbacMiddleware("superadmin", "admin_inventaris"), controller.create);
router.put("/:id", authMiddleware, rbacMiddleware("superadmin", "admin_inventaris"), controller.update);
router.put("/:id/return", authMiddleware, rbacMiddleware("superadmin", "admin_inventaris"), controller.returnLoan);
router.delete("/:id", authMiddleware, rbacMiddleware("superadmin", "admin_inventaris"), controller.delete);
export default router;
